mapper.select:
SELECT uid AS uuid, COUNT(*) AS timeNotesCount FROM b_time_notes WHERE uid IN
#{id}
GROUP BY uid

SELECT DATE_FORMAT(create_time, '%Y-%m-%d') as dateTimes, count(id) as censusSum
FROM b_time_notes
WHERE DATE_FORMAT(create_time, '%Y-%m-%d') >= #{time}
  AND uid = #{uuid}
GROUP BY DATE_FORMAT(create_time, '%Y-%m-%d')
ORDER BY DATE_FORMAT(create_time, '%Y-%m-%d')
